</script>
<a bind:this={ref} {...rest} aria-describedby={card.open ? card.popupId : undefined} data-popup-open={card.open ? '' : undefined} onpointerenter={(event) => { onpointerenter?.(event as PointerEvent & { currentTarget: EventTarget & HTMLAnchorElement }); if (!event.defaultPrevented && event.pointerType !== 'touch') schedule(true, event, delay); }} onpointerleave={(event) => { onpointerleave?.(event as PointerEvent & { currentTarget: EventTarget & HTMLAnchorElement }); if (!event.defaultPrevented) schedule(false, event, closeDelay); }} onfocus={(event) => { onfocus?.(event as FocusEvent & { currentTarget: EventTarget & HTMLAnchorElement }); if (!event.defaultPrevented) schedule(true, event, 0); }} onblur={(event) => { onblur?.(event as FocusEvent & { currentTarget: EventTarget & HTMLAnchorElement }); if (!event.defaultPrevented) schedule(false, event, closeDelay); }}>{@render children?.()}</a>
